// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.acceptedAnswers ? {acceptedAnswers: row.acceptedAnswers} : {}),
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(row.textAnswer !== undefined ? {textAnswer: row.textAnswer} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(row.acceptedNumericAnswers ? {acceptedNumericAnswers: row.acceptedNumericAnswers} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + (group.originalNumbers ? group.start : 1)), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.solutionsFile ? {solutionUrl: folder + meta.solutionsFile} : {}),
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"kit","contest":"КИТ","language":"ru","letters":"АБВГ","count":26,"year":2013,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"reviewed-8-9.pdf","points":3,"sections":[{"start":1,"title":"3 балла"},{"start":11,"title":"4 балла"},{"start":21,"title":"5 баллов"}],"reviewedKey":true}, [{"title":"Парные клавиши","question":"Какая из перечисленных клавиш стандартной QWERTY-клавиатуры не является парной?","choices":["Ctrl","Shift","Alt","Tab"],"points":3,"steps":["На стандартной клавиатуре ищи одинаковые по назначению клавиши слева и справа. Ctrl, Shift и Alt имеют такие пары.","Клавиша Tab расположена слева, рядом с буквой Q, и второй Tab справа нет."],"answer":3},{"title":"Фрукты на весах","question":"Однажды жители Лилипутии решили выяснить, сколько необходимо слив, чтобы уравновесить яблоко. При этом лилипуты выяснили, что яблоко уравновешивается на чашечных весах персиком и сливой. Два ананаса уравновешиваются тремя персиками. Яблоко и слива уравновешиваются ананасом. Помогите лилипутам решить задачу.","choices":["1","5","15","10"],"points":3,"steps":["Замени яблоко в последнем равенстве персиком и сливой. Один ананас весит как персик и две сливы, значит два ананаса — как два персика и четыре сливы.","По второму равенству этот вес равен трём персикам. Один персик равен четырём сливам, а яблоко равно персику с одной сливой, то есть пяти сливам."],"answer":1},{"title":"Оформление надписи","question":"Петя написал слово КИТ обычным шрифтом в текстовом редакторе, выделил его и последовательно нажал один раз на кнопку «полужирный», два раза на кнопку «курсив» и четыре раза на кнопку «подчёркнутый». В результате получилось…","choices":["Рисунок А","Рисунок Б","Рисунок В","Рисунок Г"],"points":3,"steps":["Первое нажатие включает свойство, второе его выключает. Два нажатия на курсив и четыре на подчёркивание оставляют обе настройки выключенными.","Один щелчок по «Полужирный» включает это свойство. Выбери надпись без наклона и подчёркивания, набранную полужирным."],"answer":1,"adaptation":"Указано исходное оформление надписи.","optionFigures":[{"src":"assets/kit/2013/8-9-03a.svg","alt":"КИТ обычным шрифтом.","width":25,"height":16},{"src":"assets/kit/2013/8-9-03b.svg","alt":"КИТ полужирным шрифтом.","width":27,"height":16},{"src":"assets/kit/2013/8-9-03c.svg","alt":"КИТ полужирным курсивом с подчёркиванием.","width":27,"height":16},{"src":"assets/kit/2013/8-9-03d.svg","alt":"КИТ курсивом с подчёркиванием.","width":25,"height":16}],"showOptionText":false},{"title":"Ряд незаконченных цифр","question":"На рисунке представлен ряд «незаконченных» цифр. Какое минимальное количество вертикальных и горизонтальных перемычек необходимо дорисовать, чтобы он стал строго возрастающей последовательностью?","choices":["6","7","8","9"],"points":3,"steps":["В ряду десять знаков, а возможных цифр ровно десять. Строго возрастающий ряд должен начинаться с 0 и включать все цифры до 9.","Цифры 1 и 3 готовы. У 0, 2, 6 и 8 нет нижней левой перемычки, у 4, 5 и 9 — верхней левой, у 7 — верхней горизонтальной. Всего 8 перемычек."],"answer":2,"figure":{"src":"assets/kit/2013/8-9-04.webp","alt":"Десять цифр из горизонтальных и вертикальных сегментов. Некоторые сегменты показаны тонкой линией.","width":525,"height":96}},{"title":"Поиск для сообщения","question":"К следующему уроку информатики Вова должен подготовить сообщение. Учитель сказал, что для сбора информации можно пользоваться Интернетом. Какой программный продукт в этом поможет Вове?","choices":["текстовый редактор","браузер","СУБД","антивирус"],"points":3,"steps":["Для сбора информации Вове нужно загружать и просматривать страницы сайтов.","Этим занимается браузер. Текстовый редактор пригодится позже для написания сообщения."],"answer":1},{"title":"Ход в крестиках-ноликах","question":"Как должен сходить игрок, играющий крестиками (сейчас его ход), чтобы следующий его ход был выигрышным при любой игре другого игрока?","choices":["B2","C2","B3","C3"],"points":3,"steps":["Крестик в C3 образует угрозу по диагонали A1–B2–C3 и по нижней строке A3–B3–C3.","Соперник за один ход закроет только B2 или B3. Оставшаяся клетка позволит достроить выигрышную линию."],"answer":3,"figure":{"src":"assets/kit/2013/8-9-06.webp","alt":"Поле с колонками A, B, C. Первая строка: крестик, пусто, нолик. Вторая: нолик, пусто, пусто. Третья: крестик, пусто, пусто.","width":193,"height":182}},{"title":"Компьютеры Macintosh","question":"Macintosh — линейка персональных компьютеров, спроектированных, разработанных, производимых и продаваемых фирмой с логотипом…","choices":["Рисунок А","Рисунок Б","Рисунок В","Рисунок Г"],"points":3,"steps":["Macintosh разработала компания Apple. IBM, Dell и Compaq — другие производители компьютеров.","Эмблема Apple изображает надкушенное яблоко. Это рисунок А."],"answer":0,"optionFigures":[{"src":"assets/kit/2013/8-9-07a.webp","alt":"Силуэт надкушенного яблока.","width":108,"height":101},{"src":"assets/kit/2013/8-9-07b.webp","alt":"Полосатая надпись IBM.","width":211,"height":104},{"src":"assets/kit/2013/8-9-07c.webp","alt":"Надпись DELL с наклонной буквой E.","width":229,"height":101},{"src":"assets/kit/2013/8-9-07d.webp","alt":"Стилизованная буква Q с надписью COMPAQ.","width":132,"height":116}],"showOptionText":false},{"title":"Отстающие часы","question":"Вася пришёл домой в 12:20. Спустя 10 минут он включил компьютер и заметил, что компьютерные часы отстают на 45 минут. Какое время показывали компьютерные часы?","choices":["11:45","13:15","13:30","11:30"],"points":3,"steps":["В момент включения компьютера настоящее время было 12:20 + 10 минут = 12:30.","Отстающие часы показывают более раннее время. Вычитаем 30 минут до 12:00 и ещё 15 минут, получаем 11:45."],"answer":0},{"title":"История программирования","question":"Первым программистом в истории человечества считается…","choices":["Ада Августа Лавлейс","Блез Паскаль","Алан Тьюринг","Чарльз Беббидж"],"points":3,"steps":["Чарльз Беббидж проектировал аналитическую машину. Ада Лавлейс описала для неё алгоритм вычисления чисел Бернулли.","Этот алгоритм считается первой опубликованной программой для вычислительной машины, поэтому ответ — Ада Августа Лавлейс."],"answer":0},{"title":"Заливка цветом","question":"Градиентом в графическом редакторе называют…","choices":["заливку одним цветом","сложный геометрический узор","растровую текстуру","плавный переход одних цветов в другие"],"points":3,"steps":["При градиенте разные участки имеют разные оттенки, например тёмно-синий, голубой и белый.","Между выбранными цветами редактор плавно меняет оттенок. Однотонная заливка и текстура такого перехода не требуют."],"answer":3},{"title":"Имя поискового сервиса","question":"Название какого поискового сервиса произошло от слова, которое означает десять в сотой степени?","choices":["Яндекс","Yahoo!","Google","Рамблер"],"points":4,"steps":["Число 10¹⁰⁰, единицу со ста нулями, называют гугол (googol).","Google получило название от английского слова googol. Оба названия начинаются на Goog."],"answer":2},{"title":"Клетки «Сапёра»","question":"Целью широко известной игры «Сапёр» является поиск незаминированных ячеек. Если в ячейке указано число, оно показывает, сколько мин скрыто в восьми ячейках вокруг данной. Это число помогает понять, где находятся безопасные ячейки. Если игрок уверен, что ячейка скрывает мину, то он помечает её флажком. На рисунке представлен фрагмент поля. Какая ячейка точно не содержит мину?","choices":["A1","D2","F1","E4"],"points":4,"steps":["Посмотри на открытую C3. В восьми соседних клетках у неё должно быть три мины. Флажки уже стоят в B2, C2 и D4.","Три соседние мины учтены, поэтому остальные соседние клетки безопасны. Среди вариантов только D2 находится рядом с C3."],"answer":1,"figure":{"src":"assets/kit/2013/8-9-12.webp","alt":"Поле «Сапёра» A–F, 1–6. Флаги в B2, C2 и D4. Открытые числа: A2 3; A3 1, B3 2, C3 3; C4 1; C5 1, D5 2, E5 2, F5 1. Серые клетки A1–F1, D2–F2, E3, F3, E4, F4 закрыты, остальные белые клетки пусты.","width":321,"height":318}},{"title":"Письмо со станции","question":"Однажды, путешествуя поездом по стране, тролль Габа вспомнил, что ему необходимо отправить электронное сообщение, но сделать это он сможет только на ближайшей станции. Известно, что следующими станциями будут Веткино, Крутилино, Жилино и Тужилино. На каждой станции есть интернет-комнаты, в работе которых предусмотрен часовой обед. На вышеперечисленных станциях он начинался в 12:00, 13:00, 14:00 и 15:00 соответственно. Когда Габа вспомнил это, его часы показывали 11 часов 40 минут. До ближайшей станции — Веткино — оставалось ехать 50 км. Скорость движения поезда — 150 км/ч. Перегоны между указанными станциями составляют 200 км. Длительность стоянок поезда на станциях 30, 10, 20 и 15 минут соответственно. В какой ближайший временной интервал троллю Габе всё же удастся отправить письмо?","choices":["15:20–15:40","13:40–14:00","12:50–13:20","17:00–17:15"],"points":4,"steps":["До Веткино 50 ÷ 150 часа, то есть 20 минут. Поезд стоит там с 12:00 до 12:30 во время обеда. На 200 км нужно 1 час 20 минут, значит стоянка в Крутилино с 13:50 до 14:00 тоже приходится на обед.","После второго перегона поезд стоит в Жилино с 15:20 до 15:40. Обед там заканчивается в 15:00, поэтому письмо впервые можно отправить здесь."],"answer":0},{"title":"Показания четырёх весов","question":"Эля решила сварить клубничное варенье. Для этого необходимо взвесить ягоды. У Эли было 4 электронных весов, одни из которых были сломаны. Все весы показывали вес в различных системах счисления. Эля взвесила одну ягодку на всех весах поочерёдно и определила, какие именно весы сломаны. Известно, что первые весы показали вес 11011₂, вторые — 200₃, третьи — 33₈, четвёртые — 102₅. Сломаны весы с номером…","choices":["1","2","3","4"],"points":4,"steps":["Переведи показания в десятичную систему. Первые весы: 16 + 8 + 2 + 1 = 27. Третьи: 3 × 8 + 3 = 27. Четвёртые: 1 × 25 + 2 = 27.","Вторые весы дали 2 × 3² = 18. Это единственное значение, отличающееся от трёх остальных."],"answer":1},{"title":"Участники сказки","question":"Участников сказки «Репка» изобразили в ряд слева направо: Репка, Дед, Бабка, Внучка, Жучка, Кошка, Мышка. Репка — самая большая, а каждый следующий участник меньше предыдущего. По какому признаку отсортированы участники?","choices":["неубыванию","убыванию","возрастанию","возрасту"],"points":4,"steps":["Сравни соседей по размеру. Репка больше Деда, он больше Бабки, и так до Мышки.","Размер при чтении слева направо уменьшается. Такой порядок называют убыванием."],"answer":1,"adaptation":"Уточнён порядок всех участников по величине."},{"title":"Уровни языков","question":"К языкам программирования высокого уровня не относится…","choices":["C#","Assembler","Ruby","Lisp"],"points":4,"steps":["C#, Ruby и Lisp позволяют описывать программы через функции или другие абстракции высокого уровня.","В Assembler команды близки к машинным инструкциям процессора, поэтому это язык низкого уровня."],"answer":1},{"title":"Три уровня дерева","question":"Двоичное дерево — древовидная структура данных, в которой каждый родительский узел имеет не более двух потомков. Пример полного двухуровневого дерева (корень не считаем за уровень), в котором очередной уровень строится из узлов, полученных из родительских добавлением к ним нуля или единицы, приведён на рисунке. Какое общее число нулей будет в полном трёхуровневом дереве на третьем уровне?","choices":["8","12","13","16"],"points":4,"steps":["На третьем уровне можно записать все восемь строк по три символа: от 000 до 111.","На каждой из трёх позиций в четырёх строках будет 0 и в четырёх 1. Всего нулей 3 × 4 = 12."],"answer":1,"figure":{"src":"assets/kit/2013/8-9-17.webp","alt":"Корень пуст. На первом уровне 0 и 1, на втором — узлы 00, 01, 10 и 11.","width":344,"height":318}},{"title":"Графические программы","question":"Установите соответствие.","choices":["1-a, 2-b, 3-c, 4-d","1-d, 2-c, 3-a, 4-b","1-b, 2-d, 3-a, 4-c","1-b, 2-a, 3-c, 4-d"],"points":4,"steps":["Corel Draw (b) редактирует векторные изображения, а Adobe Flash (d) использовался для создания анимации.","Adobe Photoshop (a) редактирует пиксели растровых изображений. Компас 3D (c) нужен для чертежей и инженерных моделей. Получается 1-b, 2-d, 3-a, 4-c."],"answer":2,"context":"a) Adobe Photoshop  ·  b) Corel Draw  ·  c) Компас 3D  ·  d) Adobe Flash\n1) векторный редактор  ·  2) анимационный пакет  ·  3) растровый редактор  ·  4) инженерный пакет"},{"title":"Зрение и речь робота","question":"Какой набор гаджетов наиболее подходит для сборки робота, обладающего слухом, зрением и возможностью общаться посредством голоса?","choices":["web-камера, микрофон, динамики","микрофон, экран, web-камера","Wi-Fi-роутер, гусеницы, микрофон","навигатор, экран, динамики"],"points":4,"steps":["Чтобы робот воспринимал изображение, нужна камера. Чтобы слышал и мог отвечать, нужны микрофон и динамики.","Первый набор содержит все три устройства. В наборе с камерой, экраном и микрофоном нечем воспроизводить голос."],"answer":0},{"title":"Поколения компьютеров","question":"Расположите в хронологическом порядке ЭВМ различных поколений: (1) транзисторные ЭВМ, (2) ламповые ЭВМ, (3) ЭВМ на базе СБИС, (4) ЭВМ на БИС.","choices":["1, 2, 3, 4","2, 1, 4, 3","1, 2, 4, 3","2, 1, 3, 4"],"points":4,"steps":["Первые из перечисленных ЭВМ строили на электронных лампах. Потом лампы заменили транзисторами.","Далее появились большие интегральные схемы (БИС), а затем сверхбольшие (СБИС). По номерам это 2, 1, 4, 3."],"answer":1},{"title":"Заливка овалов","question":"Вова нарисовал в графическом редакторе Paint несколько овалов. Некоторые из них получились незамкнутыми. Визуально холст он разбил на квадраты, каждый из которых имеет своё имя. Затем Вова взял инструмент «Заливка» и кликнул по квадрату D2. Какое количество квадратов после заливки будет закрашено целиком?","choices":["16","17","18","19"],"points":5,"steps":["Проследи распространение заливки из D2 через все разрывы. Внешний овал удерживает заливку внутри. Две небольшие замкнутые области внутри — в месте пересечений справа вверху и в центре — заливка не пересечёт.","Полные клетки по рядам: C2, D2; B3, C3, D3, G3; B4, C4, F4, G4; B5, C5, F5, G5; C6, D6, E6, F6. Это 2 + 4 + 4 + 4 + 4 = 18."],"answer":2,"figure":{"src":"assets/kit/2013/8-9-21.webp","alt":"Сетка A–H, 1–7 с замкнутыми и разомкнутыми овалами.","width":807,"height":694}},{"title":"Размер снимка","question":"Было отсканировано цветное изображение размером 10 × 15 см с разрешением 100 dpi и количеством цветов 65536. Файл был сохранён в формате bmp без сжатия. Из предложенных вариантов выберите наиболее подходящий размер файла. Напоминаем, что 1 дюйм = 2,54 см.","choices":["450,56 Мбайт","4400 Кбайт","0,44 Мбайт","1151 Кбайт"],"points":5,"steps":["Переведи размеры в дюймы и умножь на 100. Получатся примерно 394 × 591 пиксель.","Для 65536 = 2¹⁶ цветов нужно 16 бит, то есть 2 байта на пиксель. Около 466 тысяч байт делим на 1024² и получаем примерно 0,44 Мбайт."],"answer":2},{"title":"Кролики в матрице","question":"Дан фрагмент программы на языке Паскаль. Если применить данный алгоритм к матрице, заполненной кроликами, то сколько кроликов останутся нескрытыми?","choices":["15","12","13","18"],"points":5,"steps":["Циклы перебирают все 25 пар индексов. Кролик скрывается, когда остаток от деления i + j на 2 отличен от нуля, то есть индексы разной чётности.","Не скрываются пары из двух нечётных индексов (3 × 3 = 9) или двух чётных (2 × 2 = 4). Вместе 13 кроликов."],"answer":2,"context":"For i := 1 to 5 do\n  For j := 1 to 5 do\n    If (i+j) mod 2 <> 0 then\n      Write('Скрыть кролика');","figure":{"src":"assets/kit/2013/8-9-23.webp","alt":"Матрица 5 на 5, в каждой клетке по кролику.","width":437,"height":401}},{"title":"Путь голодного паука","question":"В правом верхнем углу квадрата, разбитого на 16 ячеек (число в каждой ячейке — это количество мух в ней), сидит голодный паук. За один ход он может переползти в соседнюю ячейку влево или вниз и съесть всех находящихся там мух. Чему равно наибольшее количество съеденных мух на пути паука до нижней левой ячейки включительно?","choices":[],"points":5,"steps":["В каждой клетке запиши её число мух плюс больший из накопленных результатов справа и сверху. В стартовой клетке запиши 0. В правом столбце сверху вниз будут 0, 4, 25, 42.","Суммы для третьей строки слева направо — 59, 46, 40, 25. Для нижней — 63, 52, 49, 42. Значит, в целевой клетке максимум 63. Его даёт маршрут вниз, вниз, влево, влево, влево, вниз."],"numericAnswer":63,"figure":{"src":"assets/kit/2013/8-9-24.webp","alt":"Паук в правой верхней клетке. Строки: 12, 3, 7, паук; 2, 10, 6, 4; 13, 6, 15, 21; 4, 3, 7, 17.","width":321,"height":321}},{"title":"Два циклических сдвига","question":"Пароль от почтового ящика в виде четырёхзначного числа Вася зашифровал так: цифры, занимающие чётные разряды (нумерация разрядов ведётся справа налево начиная с нуля), циклически сдвигаются вправо, а нечётные — влево на количество позиций, равных номеру разряда. Так, например, циклический сдвиг цифры 7 на четыре позиции вправо даёт нам 1 (7 → 8 → 9 → 0 → 1). Затем из нечётных цифр вычитается, а к чётным прибавляется 1. Далее оба шага повторяются ещё один раз. В результате шифровки получилось число 3216. Определите пароль.","choices":[],"points":5,"steps":["Сначала поменяй чётность каждой цифры обратно: нечётные уменьши на 1, чётные увеличь на 1. Получится 2307. Слева направо отмени сдвиги: +3, −2, +1, 0. Это 5117.","Повтори обратные шаги. Из 5117 после изменения чётности получится 4006. После обратных сдвигов получится 7816, поскольку 0 − 2 по циклу цифр даёт 8."],"numericAnswer":7816},{"title":"Поиск грибов роботом","question":"Самоделкин сконструировал робота-грибника. Робот умеет: 1) выполнять команду СОБРАТЬ — собирает гриб в той ячейке, в которой находится; 2) проверять условие ЕСЛИ есть гриб ТО … ВСЕ — позволяет выполнить какие-то действия, если ячейка, в которой он находится, «грибная». Была написана процедура ПОИСК(X, Y), которая позволяет искать и собирать грибы. Буква Г означает наличие гриба в ячейке (X, Y — координаты ячейки). Какие координаты имеет ячейка, начав с которой робот соберёт наибольшее количество грибов? Ответ запишите в виде двузначного числа, в котором координата X — число десятков, Y — число единиц.","choices":[],"points":5,"steps":["Из пустой клетки робот дальше не пойдёт. Из грибной он собирает гриб, затем пытается сходить вверх и вправо. Из верхних пяти строк можно собрать не больше четырёх грибов, по цепочкам в строке 2 или столбце 6.","Из клетки (6, 2) робот посещает (6, 3), (6, 4), (5, 4) и (6, 5), всего пять грибов. Старты правее в шестой строке пропускают один или несколько из этих грибов. Ответ 62."],"numericAnswer":62,"context":"Процедура ПОИСК(X, Y)\nНачало\n  ЕСЛИ есть гриб ТО\n    СОБРАТЬ;\n    ПОИСК(X-1, Y);\n    ПОИСК(X, Y+1);\n  ВСЕ\nКонец","figure":{"src":"assets/kit/2013/8-9-26.webp","alt":"Координата X — строка, Y — столбец. Грибы по строкам: 1 — нет; 2 — 3, 4, 5, 6; 3 — 2, 4, 6; 4 — 2, 6; 5 — 4, 6; 6 — 2, 3, 4, 5; 7 — нет.","width":487,"height":463}}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
